#include <bits/stdc++.h>
using namespace std;

const long long MODULUS = 998244353;

long long recursiveFunction(long long x, long long y, long long total, int type, vector<map<long long, long long>> &memo) {
    if (memo[type].count(total)) {
        return memo[type][total];
    }
    if (total == 1) {
        return (type == 0) ? x : y;
    }
    if (total % 2 == 1) {
        long long res = (x * recursiveFunction(x, y, total - 1, type, memo) + y * recursiveFunction(x, y, total - 1, (type + 1) % 2, memo)) % MODULUS;
        return res;
    } else {
        long long half = total / 2;
        long long ch = recursiveFunction(x, y, half, 0, memo);
        long long nch = recursiveFunction(x, y, half, 1, memo);
        long long ans;
        if (type == 0) {
            ans = (ch * ch + nch * nch) % MODULUS;
        } else {
            ans = (2 * ch * nch) % MODULUS;
        }
        memo[type][total] = ans;
        return ans;
    }
}

long long binomialCoefficient(long long x, long long st) {
    if (st == 0) return 1;
    if (st == 1) return x;
    long long half = st / 2;
    long long res = binomialCoefficient(x, half);
    if (st % 2 == 0) {
        return (res * res) % MODULUS;
    } else {
        return ((res * res) % MODULUS * x) % MODULUS;
    }
}

